import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'

export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || ''
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  ).then((res) => res.json())
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <Link href="/blog">
        <button>View All Posts</button>
      </Link>
    </div>
  )
}

import type { Metadata } from 'next'
import Link from 'next/link'

export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

export const revalidate = 60

export const metadata: Metadata = {
  title: 'Blog - My Blog',
  description: 'All blog posts',
}

export default async function BlogIndex() {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts',
    { next: { revalidate: 60 } }
  ).then((res) => res.json())

  return (
    <div>
      <h1>All Blog Posts</h1>

      <div className="posts-grid">
        {posts.map((post) => (
          <div key={post.id} className="post-card">
            <h2>
              <Link href={`/blog/${post.id}`}>{post.title}</Link>
            </h2>
            <p>{post.body.substring(0, 100)}...</p>
            <Link href={`/blog/${post.id}`}>
              <button>Read More</button>
            </Link>
          </div>
        ))}
      </div>
    </div>
  )
}

'use client'

import { useRouter } from 'next/navigation'

export default function BackButton() {
  const router = useRouter()

  return <button onClick={() => router.back()}>← Back</button>
}

import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from './BackButton'

export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

export interface Comment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

type Props = {
  params: Promise<{ id: string }>
}

export const revalidate = 300
export const dynamicParams = true

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params

  try {
    const post: Post = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}`,
      { next: { revalidate: 300 } }
    ).then((res) => res.json())

    if (!post || !post.id) {
      return {
        title: 'Post Not Found - My Blog',
      }
    }

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    }
  } catch {
    return {
      title: 'Post Not Found - My Blog',
    }
  }
}

export default async function BlogPost({ params }: Props) {
  const { id } = await params

  let post: Post
  let comments: Comment[]

  try {
    ;[post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }).then((res) => {
        if (!res.ok) throw new Error('Failed to fetch post')
        return res.json()
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }).then((res) => {
        if (!res.ok) throw new Error('Failed to fetch comments')
        return res.json()
      }),
    ])
  } catch {
    notFound()
  }

  if (!post || !post.id) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import { NextRequest, NextResponse } from 'next/server'

export interface PostItem {
  id: number
  title: string
  content: string
  createdAt?: string
}

export interface CreatePostBody {
  title?: string
  content?: string
}

export async function GET() {
  const posts: PostItem[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(request: NextRequest) {
  const body: CreatePostBody = await request.json()
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: PostItem = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextRequest, NextResponse } from 'next/server'

export interface PostDetail {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

export interface UpdatePostBody {
  title?: string
  content?: string
}

type RouteContext = {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: NextRequest,
  { params }: RouteContext
) {
  const { id } = await params

  const post: PostDetail = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext
) {
  const { id } = await params
  const body: UpdatePostBody = await request.json()
  const { title, content } = body

  const updatedPost: PostDetail = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext
) {
  const { id } = await params

  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

